<?php $currentPlan=$currentSubscription??null; $isTrial=$currentPlan && ($currentPlan['slug']??'')==='free-trial'; $isFree=$currentPlan && ($currentPlan['slug']??'free')==='free'; ?>
<section class="plans-page workspace-page"><div class="page-heading"><span class="eyebrow">خطط أثر</span><h1>اختر مساحة تناسبك</h1><p>تفاصيل الأسعار والميزات يحددها مالك الموقع. لا يتم الخصم تلقائيًا؛ رفع الطلب يرسل رغبتك إلى إدارة الموقع للتواصل والتفعيل يدويًا.</p></div>
<?php if ($currentUser && $isTrial): ?><div class="subscription-alert trial-alert" data-subscription-countdown="<?= e($currentPlan['subscription_ends_at']??'') ?>"><strong>أنت في فترة التجربة المجانية</strong><p>تنتهي في <span data-subscription-countdown-label><?= e(saudi_datetime($currentPlan['subscription_ends_at']??'')) ?></span>. ارفع طلب اشتراك قبل انتهائها.</p></div><?php elseif ($currentUser && $isFree): ?><div class="subscription-alert"><strong>أنت على الخطة الأساسية حاليًا</strong><p>بعض الميزات المتقدمة قد تكون محدودة. اختر خطة مناسبة وارفع طلب اشتراك، وسيتواصل معك مالك الموقع لتأكيد طريقة الدفع والتفعيل.</p></div><?php elseif ($currentUser): ?><div class="subscription-active-note"><strong>خطتك الحالية: <?= e($currentPlan['name']??'مشترك') ?></strong><span><?= !empty($currentPlan['subscription_ends_at'])?'تنتهي في '.e(saudi_datetime($currentPlan['subscription_ends_at'])):'اشتراكك لا يظهر له تاريخ انتهاء' ?></span></div><?php endif; ?>
<div class="owner-plan-grid public-plan-grid"><?php foreach(($plans??[]) as $plan): ?><article class="dashboard-card public-plan-card"><span class="owner-plan-pill"><?= e($plan['duration_days']) ?> يومًا</span><h2><?= e($plan['name']) ?></h2><p><?= e($plan['description']) ?></p><strong class="plan-price"><?= number_format((int)$plan['price_minor']/100,2) ?> <small><?= e($plan['currency']) ?></small></strong><ul><li>حتى <?= (int)$plan['max_sections'] ?> قسمًا</li><li>حتى <?= (int)$plan['max_evidence'] ?> دليلًا</li><?php if((int)$plan['ai_enabled']): ?><li>المساعد الذكي</li><?php endif; ?><?php if((int)$plan['custom_templates_enabled']): ?><li>القوالب المخصصة</li><?php endif; ?><?php if((int)$plan['public_sharing_enabled']): ?><li>مشاركة عامة</li><?php endif; ?><?php if((int)$plan['file_upload_enabled']): ?><li>رفع الملفات</li><?php endif; ?></ul><?php if($currentUser): ?><button type="button" class="button button-gold" data-subscription-open="<?= (int)$plan['id'] ?>" data-plan-name="<?= e($plan['name']) ?>">رفع طلب اشتراك</button><?php else: ?><a class="button button-gold" href="/register">ابدأ بإنشاء حساب</a><?php endif; ?></article><?php endforeach; ?></div><p class="helper-note">لا تحوّل مبلغًا بناءً على السعر المعروض وحده. اتفق مع مالك الموقع على وسيلة الدفع والتجديد والإلغاء أولًا.</p>
<?php if ($currentUser): ?><div class="subscription-request-panel" data-subscription-panel hidden><div class="section-card-heading"><div><span class="card-label">طلب اشتراك</span><h2>أرسل طلبك إلى إدارة الموقع</h2></div><button type="button" class="icon-button" data-subscription-close>×</button></div><form method="post" action="/subscription-request"><?= csrf_field() ?><input type="hidden" name="plan_id" data-subscription-plan><p>الخطة المختارة: <strong data-subscription-name></strong></p><label class="field"><span>رسالة إضافية (اختياري)</span><textarea name="message" rows="4" maxlength="1500" placeholder="اكتب وسيلة التواصل المناسبة أو أي ملاحظة..."></textarea></label><button class="button button-gold" type="submit">إرسال طلب الاشتراك</button></form></div><?php endif; ?></section>
